    if (p.empty() || s.empty()) { puts("0"); return 0; }
    size_t m = p.size(), n = s.size();
    // dp[i]: consecutive copies of p ending exactly at position i of s.
    vector<int> dp(n + 1, 0);
    int best = 0;
    for (size_t end = m; end <= n; end++)
        if (s.compare(end - m, m, p) == 0) { dp[end] = dp[end - m] + 1; best = max(best, dp[end]); }
