import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in), 1 << 16);
        String p = br.readLine(), s = br.readLine();
        if (p == null) p = "";
        if (s == null) s = "";
        if (p.isEmpty() || s.isEmpty()) { System.out.println(0); return; }
        int m = p.length(), n = s.length(), best = 0;
        // dp[i]: consecutive copies of p ending exactly at position i of s.
        int[] dp = new int[n + 1];
        for (int end = m; end <= n; end++)
            if (s.startsWith(p, end - m)) { dp[end] = dp[end - m] + 1; best = Math.max(best, dp[end]); }
        System.out.println(best);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
	"strings"
)

func main() {
	data, _ := io.ReadAll(os.Stdin)
	lines := strings.Split(strings.ReplaceAll(string(data), "\r\n", "\n"), "\n")
	p, s := lines[0], ""
	if len(lines) > 1 {
		s = lines[1]
	}
	if p == "" || s == "" {
		fmt.Println(0)
		return
	}
	m, n, best := len(p), len(s), 0
	// dp[i]: consecutive copies of p ending exactly at position i of s.
	dp := make([]int, n+1)
	for end := m; end <= n; end++ {
		if s[end-m:end] == p {
			dp[end] = dp[end-m] + 1
			best = max(best, dp[end])
		}
	}
	fmt.Println(best)
}
